/**
 * Site-only image variants generated by `npm run optimize-images` into the
 * gitignored `public/optimized/` folder. The original files stay untouched
 * because the Raycast extension and Open Graph images read them directly.
 */
export const OPTIMIZED_IMAGE_FOLDER = "optimized";

export const ICON_VARIANT_WIDTHS = [64, 128, 256] as const;
export type IconVariantWidth = (typeof ICON_VARIANT_WIDTHS)[number];

export const HERO_IMAGE = {
  source: "media/keycaps-hero.webp",
  width: 1280,
  height: 853,
  variantWidths: [480, 640, 960],
} as const;

export const LOGO_IMAGE = {
  source: "hotkys-logo-300x166.png",
  width: 76,
  height: 42,
  variantScales: [1, 2],
} as const;

const catalogIconPattern = /^\/icons\/([\w.-]+)\.png$/;

function stripExtension(file: string): string {
  return file.replace(/\.[^./]+$/, "");
}

export function getIconVariantPath(
  name: string,
  width: IconVariantWidth,
): string {
  return `${OPTIMIZED_IMAGE_FOLDER}/icons/${name}-${width}.webp`;
}

/**
 * Returns the URL of a generated WebP variant for a bundled catalog icon such
 * as `/icons/figma.png`. Other icons (remote or user-provided paths) have no
 * variant and are rendered as-is.
 */
export function getIconVariantUrl(
  iconUrl: string,
  width: IconVariantWidth,
): string | undefined {
  const name = catalogIconPattern.exec(iconUrl)?.[1];
  return name ? `/${getIconVariantPath(name, width)}` : undefined;
}

export function getHeroVariantPath(width: number): string {
  return `${OPTIMIZED_IMAGE_FOLDER}/${stripExtension(HERO_IMAGE.source)}-${width}.webp`;
}

export function getHeroSrcSet(): string {
  return [
    ...HERO_IMAGE.variantWidths.map(
      (width) => `/${getHeroVariantPath(width)} ${width}w`,
    ),
    `/${HERO_IMAGE.source} ${HERO_IMAGE.width}w`,
  ].join(", ");
}

export function getLogoVariantPath(scale: number): string {
  return `${OPTIMIZED_IMAGE_FOLDER}/${stripExtension(LOGO_IMAGE.source)}-${LOGO_IMAGE.width * scale}w.webp`;
}

export function getLogoSrcSet(): string {
  return LOGO_IMAGE.variantScales
    .map((scale) => `/${getLogoVariantPath(scale)} ${scale}x`)
    .join(", ");
}
